package com.learnagent.memory;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity@Table(name="knowledge_edges")public class KnowledgeEdge{@Id private UUID id;@Column(name="course_id",nullable=false)private UUID courseId;@Column(name="from_node_id",nullable=false)private UUID fromNodeId;@Column(name="to_node_id",nullable=false)private UUID toNodeId;@Enumerated(EnumType.STRING)@Column(nullable=false)private KnowledgeRelation relation;@Column(name="source_json",nullable=false,columnDefinition="text")private String sourceJson;@Column(name="created_at",nullable=false)private Instant createdAt;protected KnowledgeEdge(){}public KnowledgeEdge(UUID course,UUID from,UUID to,KnowledgeRelation relation,String source){id=UUID.randomUUID();courseId=course;fromNodeId=from;toNodeId=to;this.relation=relation;sourceJson=source;createdAt=Instant.now();}public UUID getId(){return id;}public UUID getCourseId(){return courseId;}public UUID getFromNodeId(){return fromNodeId;}public UUID getToNodeId(){return toNodeId;}public KnowledgeRelation getRelation(){return relation;}public String getSourceJson(){return sourceJson;}}
